"""Collect the checksummed Member 3 deliverables package (valid runs only) into ../deliverables/member3/ and write SUMMARY.md /
results_summary.json from the saved JSON evidence. Usage (from SparseBEV/): python3 -m outage.collect_deliverables"""
import hashlib, json, os, shutil, subprocess
P = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT = os.path.join(os.path.dirname(P), "deliverables", "member3")
J = lambda p: json.load(open(os.path.join(P, p)))
RUNS = ["pilot_a", "pilot_b", "pilot_d05", "pilot_d10", "pilot_d20", "val_a", "val_b", "val_d05", "val_d10", "val_d20"]
EVAL = ["val_a", "val_b", "val_d05", "val_d10", "val_d20"]
K = "pts_bbox_NuScenes/"
MODELS3 = ["sparsebev", "bevformer", "streampetr"]


def main():
    if os.path.exists(OUT):
        shutil.rmtree(OUT)
    os.makedirs(OUT)
    copy = ["README.md", "MODELS.md", "process.txt", "outage", "artifacts/run_matrix.sh", "artifacts/run_queue.sh", "artifacts/run_worker.sh",
            "artifacts/run_gpu_checks.sh", "artifacts/schedule_trainval_train.json", "artifacts/schedule_trainval_val.json", "artifacts/infos",
            "artifacts/provenance", "artifacts/verification_pilot.json", "artifacts/verification_val.json", "artifacts/isolation_pilot.json",
            "artifacts/input_probe", "artifacts/backbone_hook_probe.json", "artifacts/window_check_pilot.json", "artifacts/window_check_val.json",
            "artifacts/online_offline_check.json", "artifacts/cross_model_outage_check.json", "artifacts/loader_confirm_pilot.json", "artifacts/loader_confirm_val.json",
            "artifacts/projection_devkit_check.json", "artifacts/check_stats_pilot_sparsebev.json", "artifacts/check_stats_val_sparsebev.json",
            "artifacts/calibration", "artifacts/event_stats", "artifacts/superseded_geometry_v1", "artifacts/geometry_regression.json", "artifacts/check_stats_val_clean_sparsebev.json", "artifacts/code_regression.json", "artifacts/logs/status.txt", "artifacts/ckpt_records.json"]
    copy += [f"artifacts/runs/{r}" for r in RUNS] + [f"artifacts/eval/{r}/metrics.json" for r in EVAL] + \
            [f"artifacts/eval/{r}/pts_bbox/metrics_summary.json" for r in EVAL]
    for c in copy:
        s, d = os.path.join(P, c), os.path.join(OUT, c)
        if not os.path.exists(s):
            raise SystemExit(f"missing deliverable {c}")
        os.makedirs(os.path.dirname(d), exist_ok=True)
        (shutil.copytree(s, d, ignore=shutil.ignore_patterns("__pycache__", "per_sample_*.pkl") if "superseded" in c else shutil.ignore_patterns("__pycache__")) if os.path.isdir(s) else shutil.copy2(s, d))
    vp, vv, iso = J("artifacts/verification_pilot.json"), J("artifacts/verification_val.json"), J("artifacts/isolation_pilot.json")
    m = {r: J(f"artifacts/eval/{r}/metrics.json") for r in EVAL}
    gate = dict(NDS=m["val_a"][K + "NDS"], mAP=m["val_a"][K + "mAP"], ref_NDS=0.556, tol=0.010)
    gate["PASS"] = abs(gate["NDS"] - 0.556) <= 0.010
    rr = {r: J(f"artifacts/runs/{r}/run.json") for r in RUNS}
    gr = J("artifacts/geometry_regression.json")
    wv, wp, ooc = J("artifacts/window_check_val.json"), J("artifacts/window_check_pilot.json"), J("artifacts/online_offline_check.json")
    res = dict(baseline_gate=gate, official={r: {x: m[r][K + x] for x in ("NDS", "mAP", "mATE", "mASE", "mAOE", "mAVE", "mAAE")} for r in EVAL},
               verification_pilot={kk: v for kk, v in vp.items() if kk != "conditions"}, verification_val={kk: v for kk, v in vv.items() if kk != "conditions"},
               isolation={kk: v for kk, v in iso.items() if kk != "per_scene_alone_vs_continuous"}, window_check_val=wv, window_check_pilot=wp,
               online_offline=ooc, projection_devkit=J("artifacts/projection_devkit_check.json"),
               check_stats=dict(pilot=J("artifacts/check_stats_pilot_sparsebev.json"), val=J("artifacts/check_stats_val_sparsebev.json")),
               thresholds={n: J(f"artifacts/calibration/threshold_{n}.json") for n in MODELS3},
               event_pooled={n: {d: v["pooled"] for d, v in J(f"artifacts/event_stats/summary_{n}_val.json")["summary"].items()} for n in MODELS3},
               runs={r: dict({x: rr[r][x] for x in ("n_samples", "runtime_s", "latency_median_s", "peak_gpu_mb", "audit_status", "readiness",
                                                     "never_cached_before_own_frame", "history_served_from_cache_after_first_frame", "tf32_matmul", "ckpt_sha256")},
                          fresh_at_all_scene_starts=all(f for _, f in rr[r]["model_state_fresh_at_scene_starts"])) for r in RUNS})
    json.dump(res, open(os.path.join(OUT, "results_summary.json"), "w"), indent=1)
    L = ["# Member 3 deliverables — SparseBEV integration; projection, matching and official/custom evaluators; per-scene detection statistics\n",
         "Generated by `python3 -m outage.collect_deliverables`. Method, evidence and limitations: `README.md`; model/checkpoint records: `MODELS.md`.\n",
         f"## Baseline gate (declared before the result: artifacts/provenance/BASELINE_GATE_DECLARATION.txt)\nNDS {gate['NDS']:.4f} vs released 0.556 (tolerance ±0.010) -> **{'PASS' if gate['PASS'] else 'FAIL'}**; mAP {gate['mAP']:.4f} (not gated: the release publishes no mAP).\n",
         "## Official nuScenes metrics, full validation (150 scenes, 6019 samples), whole-sequence\n| run | NDS | mAP | mATE | mASE | mAOE | mAVE | mAAE |\n|---|---|---|---|---|---|---|---|"]
    for r in EVAL:
        o = res["official"][r]; L.append(f"| {r} | " + " | ".join(f"{o[x]:.4f}" for x in ("NDS", "mAP", "mATE", "mASE", "mAOE", "mAVE", "mAAE")) + " |")
    L.append("\nWhole-sequence scores dilute a brief single-camera outage; no significance is claimed here (bootstrap: Member 4).\n")
    for name, v in (("Pilot (10 training-split scenes, 402 samples)", vp), ("Full validation (150 scenes, 6019 samples)", vv)):
        L += [f"## {name}\nClean twice: max |diff| = {v['clean_twice_max_abs_diff']} over {v['clean_twice_identical_samples']} samples; clean audits {v['clean_audit_a']}/{v['clean_audit_b']}; paired input errors {v['clean_a_vs_b_input_errors']}.\n",
              "| outage | audit | paired-input errors | black = independent recomputation | black images | all-black pixels | other cams touched | prefix preds identical | post-start preds changed | scenes w/ missing bins |",
              "|---|---|---|---|---|---|---|---|---|---|"]
        for n, c in v["conditions"].items():
            L.append(f"| {n} | {c['status']} | {c['n_paired_errors']} | {c['black_inputs_expected_vs_logged_equal']} | {c['n_black_images']} | {c['all_black_pixels_verified']} | "
                     f"{c['other_cameras_corrupted']} | {c['prefix_predictions_identical']}/{c['prefix_samples']} | {c['post_start_predictions_changed']}/{c['post_start_samples']} | {len(c['missing_follow_up_bins'])} |")
        L.append("")
    L += ["## Finite-window contamination check (plan: temporal contamination), full validation\n| outage | non-contaminated samples | max |diff| vs clean | contaminated samples | changed | last black frame leaves history (s after restoration: min / median / max) |\n|---|---|---|---|---|---|"]
    for n, w in wv["runs"].items():
        lv = w["leave_offset_s_after_restoration"]
        L.append(f"| {n} | {w['n_noncontaminated']} | {w['noncontaminated_max_abs_diff']} | {w['n_contaminated']} | {w['contaminated_changed']} | {lv['min']:.2f} / {lv['median']:.2f} / {lv['max']:.2f} |")
    L += [f"\nPASS = {wv['PASS']} (every sample whose 8-keyframe window holds no black front image equals the clean run within {wv['tol']}).\n",
          f"## Real-model state isolation (pilot)\nall_isolated = {iso['all_isolated']}; every scene alone == continuous run (max diffs {sorted({v['max_abs_diff'] for v in iso['per_scene_alone_vs_continuous'].values()})}); "
          f"fresh B twice {iso['fresh_B_twice_max_abs_diff']}; B after A {iso['B_after_A_vs_fresh_B_max_abs_diff']}; interleave rejected ({iso['interleave_control']['rejected']}). "
          f"Stale-cache control (outage run of the first 7 samples, then clean full run without reset): rejected by the guard = {iso['stale_cache_control']['rejected_by_guard']}; "
          f"unguarded, sample 6 reuses the black features (equals the outage run: {iso['stale_unguarded_sample6_equals_outage_run']}). A full-scene rerun without reset gets no stale hit "
          f"(guard fired: {iso['full_run_then_rerun_without_reset']['rejected_by_guard']}; FIFO-8 evicts the leftover tail first).\n",
          f"## Online vs offline execution path (clean inputs only, pilot subset)\n{ooc}\nClean-input equivalence only; offline outage inference is not implemented or established.\n",
          "## Evaluator checks\n" + "\n".join([
              f"* Projection / eligibility vs nuScenes devkit: {res['projection_devkit']['n_boxes']} boxes, max centre diff {res['projection_devkit']['max_abs_center_diff_m']:.1e} m, max pixel diff {res['projection_devkit']['max_abs_pixel_diff']:.4f} px, flag mismatches {res['projection_devkit']['region_flag_mismatches']}/{res['projection_devkit']['eligible_flag_mismatches']}",
              f"* Independent re-implementation of per-sample counts: pilot {res['check_stats']['pilot']['n_samples']} samples PASS={res['check_stats']['pilot']['PASS']}; val subset {res['check_stats']['val']['n_samples']} samples PASS={res['check_stats']['val']['PASS']} (+ clean subset incl. the Inspector's sample)",
              f"* Geometry v2 (one ego ground plane for region and matching) — v1 superseded after the Inspector's finding; regression: {gr['example']['v1_status']} -> {gr['example']['v2_status']} (LiDAR-XY {gr['example']['lidar_xy_distance_m']:.4f} m vs ego plane {gr['example']['ego_plane_geometric_centre_distance_m']:.4f} m); samples with changed counts per run: " + "; ".join(f"{t}: " + "/".join(str(v['samples_with_changed_counts']) for v in c['runs'].values()) for t, c in gr['comparison'].items()),
              "* Controlled-example unit tests: outage/tests/test_evaluator.py (45, incl. pitched/rolled-LiDAR ground-plane cases)"]) + "\n",
          "## Calibrated thresholds (pilot, clean predictions; frozen before validation event analysis)\n| model | tau | precision | recall | predictions | native score floor |\n|---|---|---|---|---|---|"]
    for n in MODELS3:
        t = res["thresholds"][n]; L.append(f"| {n} | {t['tau']:.4f} | {t['precision']:.3f} | {t['recall']:.3f} | {t['n_pred']} | {t['native_score_floor']:.4f} |")
    L += ["\n## Pooled front-region recall loss L = R_clean - R_outage (full validation; plain aggregation, intervals are Member 4's)\n| model | outage | during | b0.0 | b0.5 | b1.0 | b2.0 | b3.0 | b4.0 |\n|---|---|---|---|---|---|---|---|---|"]
    for n in MODELS3:
        for d, pool in res["event_pooled"][n].items():
            L.append(f"| {n} | {d} s | " + " | ".join("n/a" if pool[ph]["loss"] is None else f"{pool[ph]['loss']:.3f}" for ph in ("during", "b0.0", "b0.5", "b1.0", "b2.0", "b3.0", "b4.0")) + " |")
    L += ["\n## Runs\n| run | samples | runtime s | median latency s | peak GPU MB | audit | readiness | own frame uncached at scene starts | history served from cache |\n|---|---|---|---|---|---|---|---|---|"]
    for r in RUNS:
        x = res["runs"][r]
        L.append(f"| {r} | {x['n_samples']} | {x['runtime_s']:.0f} | {x['latency_median_s']:.3f} | {x['peak_gpu_mb']:.0f} | {x['audit_status']} | {x['readiness'][:45]} | {x['fresh_at_all_scene_starts']} | {x['history_served_from_cache_after_first_frame']} |")
    L.append("\nLatency here is end-to-end per frame (JPEG decode + pipeline + model, 2 concurrent processes), NOT the isolated batch-one GPU latency (Member 4's profiling).")
    open(os.path.join(OUT, "SUMMARY.md"), "w").write("\n".join(L) + "\n")
    files = sorted(os.path.relpath(os.path.join(r, f), OUT) for r, _, fs in os.walk(OUT) for f in fs)
    with open(os.path.join(OUT, "SHA256SUMS"), "w") as f:
        for p in files:
            f.write(f"{hashlib.sha256(open(os.path.join(OUT, p), 'rb').read()).hexdigest()}  {p}\n")
    print("\n".join(L[:10])); print(len(files), "files ->", OUT)
    print(subprocess.run(["du", "-sh", OUT], capture_output=True, text=True).stdout)


if __name__ == "__main__":
    main()
